class GenericGameSaver {
public:
    bool hasSystemFile(int port, int slot);
};

bool GenericGameSaver::hasSystemFile(int port, int slot)
{
    sceMcTblGetDir listing[10] __attribute__((aligned(64)));
    stringx name = stringx("/") + stringx("BASLUS-20334") + "/" + stringx("BASLUS-20334");
    char dirList[100];
    int cmd, result;
    strcpy(dirList, name.c_str());

    if (sceMcGetDir(port, slot, dirList, 0, 10, listing) != 0)
        if (sceMcGetDir(port, slot, dirList, 0, 10, listing) != 0)
            return false;

    if (sceMcSync(0, &cmd, &result) != 1)
    {
        if (sceMcGetDir(port, slot, dirList, 0, 10, listing) != 0)
        {
            if (sceMcGetDir(port, slot, dirList, 0, 10, listing) != 0)
            {
                return false;
            }
            else
            {
                if (sceMcSync(0, &cmd, &result) != 1)
                    return false;
            }
        }
        else
        {
            if (sceMcSync(0, &cmd, &result) != 1)
                return false;
        }
    }
    return result > 0;
}
